#include <iostream>
#include <queue>
#include <functional>
#include <string>
using namespace std;

class TaskQueue {
    queue<function<void()>> tasks;
public:
    void enqueue(function<void()> task) { tasks.push(task); }
    bool hasNext() { return !tasks.empty(); }
    function<void()> dequeue() { auto t = tasks.front(); tasks.pop(); return t; }
};

int main() {
    TaskQueue tq;
    tq.enqueue([]() { cout << "Task 1: Process data" << endl; });
    tq.enqueue([]() { cout << "Task 2: Send email" << endl; });
    tq.enqueue([]() { cout << "Task 3: Generate report" << endl; });
    tq.enqueue([]() { cout << "Task 4: Backup files" << endl; });
    tq.enqueue([]() { cout << "Task 5: Clean cache" << endl; });

    int workerId = 1;
    while (tq.hasNext()) {
        cout << "Worker " << workerId << ": ";
        tq.dequeue()();
        workerId = (workerId % 3) + 1;
    }
    return 0;
}
